  new(79,"PED:US-CCSS-MATH:G2:U05:L12","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-12/preparation.html","d9f984f116a632952be392c86686a9edd194a880c1123e119b6b744927163872",
  ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.4","CCSS:2.NBT.B.8"],
  ["Learning goal: You will order numbers from least to greatest and greatest to least.\nIn previous lessons, you learned to compare three-digit numbers using the value of each digit. You have used the number line and base-ten diagrams to compare numbers and explain your thinking. The purpose of this lesson is for you to compare three-digit numbers and place them in order from least to greatest and from greatest to least.",
   "Key ideas:\n- Order three-digit numbers using place value understanding and the relative position of numbers on a number line\n- In previous lessons, you learned to compare three-digit numbers using the value of each digit\n- Compare actual values or measured attributes, not the visual size or position of a drawing.",
   "Example 1: Find the value of each expression mentally. \\(80 - 50\\) \\(87 - 50\\) \\(76 - 40\\) \\(66 - 30\\)\nApproach: “How could the third expression help you find the value of the last expression?” (76 is 10 more than 66 and 30 is 10 less than 40, so the difference between the two numbers is the same.)\nExample 2: Kiran and Andre put a list of numbers in order from least to greatest. Kiran 207, 217, 272, 269, 290 Andre 207, 217, 269, 272, 290 Andre disagreed with Kiran, so he used a number line to justify his answer. Who do you agree with? Why? Be prepared to explain your thinking. Use what you know about place value or the number line to justify your reasoning.\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.",
   "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
   "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
   "You will order numbers from least to greatest and greatest to least. In previous lessons, you learned to compare three-digit numbers using the value of each digit."],
  ["IM2021 original Grade2 Unit5 Lesson12 Order Numbers. Original Number Talk subtract tens:80−50=30,87−50=37,76−40=36,66−30=36. Activity1 Kiran falsely orders207,217,272,269,290; Andre accurately orders207,217,269,272,290 and source line200..300 supports it. Activity2 from700..850 original points839,765,788,815,719 sorted ASC719,765,788,815,839. Second original100..250 plot points199,245,173,218,137 sorted DESC245,218,199,173,137. Third source set545,454,405,504,445 sorted ASC405,445,454,504,545. Students genuinely draw and explain. Source math: When ordering multiple three-digit numbers compare hundreds, then tens, then ones; number-line points increase left to right. An ascending sequence cannot have272 before269. A line labelled by tens has between-tick positions for non-multiples of ten; place original dots accurately. Real teacher tasks: Original figure with five real plotted points, pupil hand-drawn number-line locations and partner justifications human reviewed; protected Cool-down not auto-generated.",
   "Lesson-specific rules: When ordering multiple three-digit numbers compare hundreds, then tens, then ones; number-line points increase left to right. An ascending sequence cannot have272 before269. A line labelled by tens has between-tick positions for non-multiples of ten; place original dots accurately. Original source activity essential evidence: Activity1 Kiran falsely orders207,217,272,269,290; Andre accurately orders207,217,269,272,290 and source line200..300 supports it. Activity2 from700..850 original points839,765,788,815,719 sorted ASC719,765,788,815,839. Second original100..250 plot points199,245,173,218,137 sorted DESC245,218,199,173,137. Third source set545,454,405,504,445 sorted ASC405,445,454,504,545. Students genuinely draw and explain. Official standards: CCSS:2.NBT.A.1, CCSS:2.NBT.A.4, CCSS:2.NBT.B.8.",
   "ORIGINAL SOURCE (teacher/public math tasks, paraphrased): Original30,37,36,36; Andre207,217,269,272,290; ASC719,765,788,815,839; DESC245,218,199,173,137; ASC405,445,454,504,545. The source-specific image, physical work and student response require actual educator inspection. Other generated examples in Edulytics are FIRST-PARTY, not copied publisher restricted assessment.",
   "1. Review true original publisher warm-up: Original Number Talk subtract tens:80−50=30,87−50=37,76−40=36,66−30=36. 2. Examine source student-facing tasks and materials: Activity1 Kiran falsely orders207,217,272,269,290; Andre accurately orders207,217,269,272,290 and source line200..300 supports it. Activity2 from700..850 original points839,765,788,815,719 sorted ASC719,765,788,815,839. Second original100..250 plot points199,245,173,218,137 sorted DESC245,218,199,173,137. Third source set545,454,405,504,445 sorted ASC405,445,454,504,545. Students genuinely draw and explain. 3. Show original numeric and place-value strategies: When ordering multiple three-digit numbers compare hundreds, then tens, then ones; number-line points increase left to right. An ascending sequence cannot have272 before269. A line labelled by tens has between-tick positions for non-multiples of ten; place original dots accurately. 4. Discuss plausible misconception and accurate solution with specific source values: Kiran's 272 before269 is out of order. Don't treat original source line as a list of only printed multiples of10. Sorting a set isn't demonstrated by an answer about only its largest number. 5. Finish actual source images/cards/games/drawings with educator; do NOT invent values not available as text. 6. Complete separate original Edulytics numeric practice with exact re-verification and teacher-graded open parts. 7. Preserve teacher assessment boundary: Original figure with five real plotted points, pupil hand-drawn number-line locations and partner justifications human reviewed; protected Cool-down not auto-generated.",
   "Mathematically inappropriate actions: Kiran's 272 before269 is out of order. Don't treat original source line as a list of only printed multiples of10. Sorting a set isn't demonstrated by an answer about only its largest number. Do not claim numeric answer certifies original image, physical block/card game, number-line dot or class oral practice.",
   "Source IM2021 G2 Unit5 L12. When ordering multiple three-digit numbers compare hundreds, then tens, then ones; number-line points increase left to right. An ascending sequence cannot have272 before269. A line labelled by tens has between-tick positions for non-multiples of ten; place original dots accurately. Original figure with five real plotted points, pupil hand-drawn number-line locations and partner justifications human reviewed; protected Cool-down not auto-generated."]),
  new(80,"PED:US-CCSS-MATH:G2:U05:L13","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-13/preparation.html","7a30437f3829c361752b815cda9061668a8c10e4979ba3f95f3fded193475ff6",
  ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.4"],
  ["Learning goal: You will order, compare, and describe three-digit numbers using your understanding of place value.\nThis lesson is optional because it is an opportunity for extra practice that not all classes may need. In Activity 1, you learn a new stage of the Get Your Numbers in Order center, which was first introduced in grade 1. In this stage, you use your understanding of relative magnitude to order three-digit numbers.",
   "Key ideas:\n- Order, compare, and describe three-digit numbers using place value understanding\n- This lesson is optional because it is an opportunity for extra practice that not all classes may need\n- Compare actual values or measured attributes, not the visual size or position of a drawing.",
   "Example 1: How many do you see and how do you see them?\nApproach: “How are these images the same? How are you different?” (You each show 6 of a unit and 4 of a unit. You each have one unit that has 0. You are different because the size of the unit is different. You each represent a different number.) “Which image represents the greatest value? How do you know?” (604 is the greatest because it has 6 hundreds.)",
   "Step 1: Identify the quantities or expressions to compare.\nStep 2: Represent or calculate each value accurately.\nStep 3: Decide whether one is greater, less, or equal.\nStep 4: Write or explain the comparison.\nStep 5: Recheck both values before finalizing.",
   "Common mistake: deciding from appearance instead of actual values. Represent or calculate both quantities before comparing.",
   "You will order, compare, and describe three-digit numbers using your understanding of place value. This lesson is optional because it is an opportunity for extra practice that not all classes may need."],
  ["IM2021 original Grade2 Unit5 Lesson13 Center Day 2 (optional). Original How Many Do You See? diagrams are6 hundreds4 ones=604,4 hundreds6 ones=406,6 tens4 ones=64. Same piece counts can represent different values because units differ. OPTIONAL Activity1 Get Your Numbers in Order Stage2 with actual deck number cards0–9 (remove10) and original gameboard; draw THREE cards each turn to create 3-digit number and insert into increasing order, or say pass and gain1 point when no valid slot. Player with FEWEST points when board filled wins. Activity2 choice of previous genuine centers; actual game states depend on class. Source math: 604>406>64, since the hundreds, tens, ones positions determine value. A new3-digit card number must fit at a vacant ordered slot; pass and gain1 point if none. Three randomly drawn physical cards may form multiple mathematically valid three-digit numbers; pupil strategy and result require teacher. Real teacher tasks: Actual original Stage2 board, randomly drawn cards, pass decisions, points and choice center student class observed only; no original Cool-down.",
   "Lesson-specific rules: 604>406>64, since the hundreds, tens, ones positions determine value. A new3-digit card number must fit at a vacant ordered slot; pass and gain1 point if none. Three randomly drawn physical cards may form multiple mathematically valid three-digit numbers; pupil strategy and result require teacher. Original source activity essential evidence: OPTIONAL Activity1 Get Your Numbers in Order Stage2 with actual deck number cards0–9 (remove10) and original gameboard; draw THREE cards each turn to create 3-digit number and insert into increasing order, or say pass and gain1 point when no valid slot. Player with FEWEST points when board filled wins. Activity2 choice of previous genuine centers; actual game states depend on class. Official standards: CCSS:2.NBT.A.1, CCSS:2.NBT.A.4.",
   "ORIGINAL SOURCE (teacher/public math tasks, paraphrased): Original images604,406,64; game illustrative first-party synthetic cards can make3-digit values, but no observed source card numbers claimed. The source-specific image, physical work and student response require actual educator inspection. Other generated examples in Edulytics are FIRST-PARTY, not copied publisher restricted assessment.",
   "1. Review true original publisher warm-up: Original How Many Do You See? diagrams are6 hundreds4 ones=604,4 hundreds6 ones=406,6 tens4 ones=64. Same piece counts can represent different values because units differ. 2. Examine source student-facing tasks and materials: OPTIONAL Activity1 Get Your Numbers in Order Stage2 with actual deck number cards0–9 (remove10) and original gameboard; draw THREE cards each turn to create 3-digit number and insert into increasing order, or say pass and gain1 point when no valid slot. Player with FEWEST points when board filled wins. Activity2 choice of previous genuine centers; actual game states depend on class. 3. Show original numeric and place-value strategies: 604>406>64, since the hundreds, tens, ones positions determine value. A new3-digit card number must fit at a vacant ordered slot; pass and gain1 point if none. Three randomly drawn physical cards may form multiple mathematically valid three-digit numbers; pupil strategy and result require teacher. 4. Discuss plausible misconception and accurate solution with specific source values: Classifying the three pictures by number of blocks rather than unit SIZE confuses604 with64. Never invent source board slots, actual turns or game winners. Center is optional. 5. Finish actual source images/cards/games/drawings with educator; do NOT invent values not available as text. 6. Complete separate original Edulytics numeric practice with exact re-verification and teacher-graded open parts. 7. Preserve teacher assessment boundary: Actual original Stage2 board, randomly drawn cards, pass decisions, points and choice center student class observed only; no original Cool-down.",
   "Mathematically inappropriate actions: Classifying the three pictures by number of blocks rather than unit SIZE confuses604 with64. Never invent source board slots, actual turns or game winners. Center is optional. Do not claim numeric answer certifies original image, physical block/card game, number-line dot or class oral practice.",
   "Source IM2021 G2 Unit5 L13. 604>406>64, since the hundreds, tens, ones positions determine value. A new3-digit card number must fit at a vacant ordered slot; pass and gain1 point if none. Three randomly drawn physical cards may form multiple mathematically valid three-digit numbers; pupil strategy and result require teacher. Actual original Stage2 board, randomly drawn cards, pass decisions, points and choice center student class observed only; no original Cool-down."]),
  new(81,"PED:US-CCSS-MATH:G2:U05:L14","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-14/preparation.html","2307697a58c5ea48f96a77a5bc2cc12761f65f60aa16ce7fe4d0a3c87193ccab",
  ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.2"],
  ["Learning goal: You will apply your understanding of place value to count real-world objects.\nThis lesson is optional because it does not address any new mathematical content standards. This lesson does provide you with an opportunity to apply precursor skills of mathematical modeling. In this lesson, you build on your previous understandings and experiences with representations of numbers between 100 and 999.",
   "Key ideas:\n- Count and represent three-digit numbers using place value understanding\n- This lesson is optional because it does not address any new mathematical content standards\n- Choose a representation that matches the quantities and relationship, then use it to justify and check the result.",
   "Example 1: Clare, Noah, and Jada counted a cup of dried beans. They each came up with 529 beans. The following pictures show how each of them counted. Jada’s counting strategy: Noah’s counting strategy: Clare’s counting strategy: What do you notice about each of their strategies? What is helpful about each strategy? What is challenging about each strategy?\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.\nExample 2: Organize and count your beans. Use the space to record your thinking. Gallery walk questions: How does this strategy help you count their beans? How can this be made clearer? How is this strategy the same as your strategy? How is it different? Does your group have more or fewer beans? Explain your reasoning.\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.",
   "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
   "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
   "You will apply your understanding of place value to count real-world objects. This lesson is optional because it does not address any new mathematical content standards."],
  ["IM2021 original Grade2 Unit5 Lesson14 Hundreds of Objects (optional). Original Notice/Wonder real jar of beans photograph, discuss perceived count and efficient grouping, not a provided exact jar count. OPTIONAL source Clare/Noah/Jada each report exactly529 beans in ONE original cup, via different grouped methods: Jada groups5, Noah groups10, Clare place-value groups. Compare relative efficiency and risk of recounting. Activity2 real student pairs or groups count DIFFERENT physical cup amount of beans (half to one cup), record each number and original strategy on sticky note, do gallery walk and comparison; class total is not given. Source math: Five hundred twenty-nine is 5 hundreds2 tens9 ones=529. Any correctly counted grouping by5,10 or100 with leftover items must sum to the same object count. Physical collections have actual unknown totals; don't label all cups529. Checking recount/double count is a human process. Real teacher tasks: Teacher observes original image, authentic collection counts, strategy diagrams, partner group gallery, actual sticky-note totals; protected Cool-down not available.",
   "Lesson-specific rules: Five hundred twenty-nine is 5 hundreds2 tens9 ones=529. Any correctly counted grouping by5,10 or100 with leftover items must sum to the same object count. Physical collections have actual unknown totals; don't label all cups529. Checking recount/double count is a human process. Original source activity essential evidence: OPTIONAL source Clare/Noah/Jada each report exactly529 beans in ONE original cup, via different grouped methods: Jada groups5, Noah groups10, Clare place-value groups. Compare relative efficiency and risk of recounting. Activity2 real student pairs or groups count DIFFERENT physical cup amount of beans (half to one cup), record each number and original strategy on sticky note, do gallery walk and comparison; class total is not given. Official standards: CCSS:2.NBT.A.1, CCSS:2.NBT.A.2.",
   "ORIGINAL SOURCE (teacher/public math tasks, paraphrased): Publisher first cup three student methods each report529, not a general promise every cup has529; first-party examples may use newly invented counts as hypothetical only. The source-specific image, physical work and student response require actual educator inspection. Other generated examples in Edulytics are FIRST-PARTY, not copied publisher restricted assessment.",
   "1. Review true original publisher warm-up: Original Notice/Wonder real jar of beans photograph, discuss perceived count and efficient grouping, not a provided exact jar count. 2. Examine source student-facing tasks and materials: OPTIONAL source Clare/Noah/Jada each report exactly529 beans in ONE original cup, via different grouped methods: Jada groups5, Noah groups10, Clare place-value groups. Compare relative efficiency and risk of recounting. Activity2 real student pairs or groups count DIFFERENT physical cup amount of beans (half to one cup), record each number and original strategy on sticky note, do gallery walk and comparison; class total is not given. 3. Show original numeric and place-value strategies: Five hundred twenty-nine is 5 hundreds2 tens9 ones=529. Any correctly counted grouping by5,10 or100 with leftover items must sum to the same object count. Physical collections have actual unknown totals; don't label all cups529. Checking recount/double count is a human process. 4. Discuss plausible misconception and accurate solution with specific source values: Assuming all actual groups count529 because original demonstration cup did. Losing remainder or double-counting piles. Claiming numeric online practice establishes real bean count or source photo evidence. 5. Finish actual source images/cards/games/drawings with educator; do NOT invent values not available as text. 6. Complete separate original Edulytics numeric practice with exact re-verification and teacher-graded open parts. 7. Preserve teacher assessment boundary: Teacher observes original image, authentic collection counts, strategy diagrams, partner group gallery, actual sticky-note totals; protected Cool-down not available.",
   "Mathematically inappropriate actions: Assuming all actual groups count529 because original demonstration cup did. Losing remainder or double-counting piles. Claiming numeric online practice establishes real bean count or source photo evidence. Do not claim numeric answer certifies original image, physical block/card game, number-line dot or class oral practice.",
   "Source IM2021 G2 Unit5 L14. Five hundred twenty-nine is 5 hundreds2 tens9 ones=529. Any correctly counted grouping by5,10 or100 with leftover items must sum to the same object count. Physical collections have actual unknown totals; don't label all cups529. Checking recount/double count is a human process. Teacher observes original image, authentic collection counts, strategy diagrams, partner group gallery, actual sticky-note totals; protected Cool-down not available."])
 ];
 private static Entry? Find(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>
  d.PackCode==MathematicsCurriculumPackRegistry.CommonCoreCode&&d.VersionCode=="CCSSM-2010"&&
  d.ContentVersion=="phase30-common-core-rich-content-v1"?Contracts.SingleOrDefault(x=>x.Code==l.LessonCode):null;
 public static bool IsTarget(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>Find(d,l)!=null;
 public static string VersionFor(int ordinal)=>$"usccss-g2-u05-original-ordinal{ordinal}-v2";
 private static void Check(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,Entry x)
 {
   if(x.Url!=l.SourceUrl||!string.Equals(l.CanonicalBodySha256,x.Sha,StringComparison.OrdinalIgnoreCase)||
      !l.OutcomeCodes.SequenceEqual(x.Outcomes))throw new InvalidOperationException($"G2 U05 source drift ordinal{x.Ordinal}");
 }
 private static bool Same(string[] values,string[] b)=>values.SequenceEqual(b);
 private static string[] Fields(CanonicalLessonContentPackTranslation x)=>
  [x.Explanation,x.KeyConceptsAndRules,x.WorkedExamples,x.StepByStepSolutions,x.CommonMistakes,x.QuickSummary];
 private static string[] Fields(CurriculumLessonContentTranslation x)=>
  [x.Explanation,x.KeyConceptsAndRules,x.WorkedExamples,x.StepByStepSolutions,x.CommonMistakes,x.QuickSummary];
 public static void Apply(CanonicalLessonContentPackDocument d)
 {
   foreach(var l in d.Lessons)
   {
     var x=Find(d,l);if(x==null)continue;Check(d,l,x);
     var t=l.Translations.Single(x=>x.CultureCode=="en");
     if(Same(Fields(t),x.After))continue;
     if(!Same(Fields(t),x.Before))throw new InvalidOperationException($"G2 U05 unexpected predecessor ordinal{x.Ordinal}");
     t.Explanation=x.After[0];t.KeyConceptsAndRules=x.After[1];t.WorkedExamples=x.After[2];
     t.StepByStepSolutions=x.After[3];t.CommonMistakes=x.After[4];t.QuickSummary=x.After[5];
   }
 }
 public static string GetExpectedContentVersion(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)
 {
    var x=Find(d,l);return x is null?prior:VersionFor(x.Ordinal);
 }
 public static bool CanUpgradeExisting(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)=>
    Find(d,l)!=null&&prior==CommonCoreRichContentCorrections.CorrectionContentVersion;
 public static void ValidateExistingBodyBeforeUpgrade(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,
   string prior,IReadOnlyCollection<CurriculumLessonContentTranslation> rows)
 {
   var x=Find(d,l)??throw new InvalidOperationException("Not a G2 U05 source target");Check(d,l,x);
   if(!CanUpgradeExisting(d,l,prior))throw new InvalidOperationException("Unapproved persisted prior version");
   if(rows.Count==0)return;
   if(rows.Count!=1||rows.Single().CultureCode!="en"||!Same(Fields(rows.Single()),x.Before))
     throw new InvalidOperationException($"G2 ordinal{x.Ordinal} persisted source fields differ");
 }
